.page-header {
  width: 100%;
  max-width: 820px;
  margin-bottom: 36px;
}

.page-header h1 {
  font-size: 1.35rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--text-primary);
}

.page-header p {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-top: 4px;
}

/* ── Image Card ── */
.image-card {
  width: 100%;
  max-width: 820px;
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.image-card__preview {
  width: 100%;
  aspect-ratio: 16 / 9;
  background: linear-gradient(135deg, #1c1c2e 0%, #2a1f3d 40%, #1a2a3a 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.image-card__preview::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 50% at 30% 40%, rgba(120, 80, 200, 0.18) 0%, transparent 70%),
    radial-gradient(ellipse 50% 60% at 70% 65%, rgba(40, 120, 200, 0.14) 0%, transparent 70%);
}

.image-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  color: var(--text-muted);
  position: relative;
  z-index: 1;
}

.image-placeholder svg {
  opacity: 0.5;
}

.image-placeholder span {
  font-size: 0.8rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.image-card__meta {
  padding: 20px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  border-top: 1px solid var(--border-subtle);
}

.image-info {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.image-info__name {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-primary);
}

.image-info__details {
  font-size: 0.78rem;
  color: var(--text-muted);
}

.image-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* ── Buttons ── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-size: 0.85rem;
  font-weight: 500;
  cursor: pointer;
  border: none;
  transition: background var(--transition-fast), color var(--transition-fast), box-shadow var(--transition-fast);
  white-space: nowrap;
  line-height: 1;
}

.btn--ghost {
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border-subtle);
}

.btn--ghost:hover {
  background: var(--btn-ghost-hover);
